var matchReplayClip=null,matchReplayList=null,matchReplayAge=0,matchReplayPlaying=false,matchReplaySpeed=1,matchReplayRAF=null,matchReplayClock=null,matchReplayOpener=null,matchReplayPhase=null,matchReplaySize=null,matchReplayEntryStamp='',matchReplayNames=[];
const matchReplayDialog=document.createElement('dialog');matchReplayDialog.id='match-replay-dialog';matchReplayDialog.setAttribute('aria-labelledby','match-replay-title');matchReplayDialog.setAttribute('aria-modal','true');document.body.append(matchReplayDialog);
const matchReplayPainter=PitchArt.createRenderer(()=>document.createElement('canvas'));
function renderMatchReplayEntry(){
 if(view!=='match'||matchPopupActive!=='stats'||state!==season.match||typeof practiceSession!=='undefined'&&practiceSession)return;
 const host=$('match-replay-entry');if(!host)return;const shotMode=typeof matchReportTab!=='undefined'&&matchReportTab==='슈팅 위치'&&typeof ShotReport!=='undefined',shot=shotMode?ShotReport.read(typeof visibleMatchForReports==='function'?visibleMatchForReports():state,{team:shotReportFilter,selected:shotReportSelection}).selected:null;const key=state.seed+':'+state.minute+':'+state.logs.length+':'+(pendingVisibleMatchEvent()?state.logs.indexOf(pendingVisibleMatchEvent()):'ready')+':'+(shotMode?shot?.key||'no-shot':'all');if(key===matchReplayEntryStamp)return;matchReplayEntryStamp=key;
 const list=MatchReplay.read(season,{pendingEvent:pendingVisibleMatchEvent()});const chosen=shotMode?MatchReplay.sceneForShot(season,shot,{pendingEvent:pendingVisibleMatchEvent()}):null;host.hidden=shotMode?!chosen:!list.scenes.length;
 if(list.scenes.length)host.innerHTML='<button type="button" id="match-replay-open" class="secondary">'+(chosen?'선택 슈팅 다시 보기 · '+shot.minute+'′':'주요 장면 다시 보기 · '+list.scenes.length+'개')+'</button>';
 const button=$('match-replay-open');if(button)button.onclick=()=>openMatchReplay(button,chosen?.id);
}
function stopMatchReplay(){matchReplayPlaying=false;matchReplayClock=null;if(matchReplayRAF!==null){cancelAnimationFrame(matchReplayRAF);matchReplayRAF=null;}const button=$('match-replay-play');if(button){button.textContent=matchReplayAge>=matchReplayClip?.duration?'처음부터 재생':'장면 재생';button.setAttribute('aria-pressed','false');}}
function measureMatchReplay(){matchReplayNames=[];const canvas=$('match-replay-field');if(!canvas)return;const rect=canvas.getBoundingClientRect(),dpr=Math.min(2,window.devicePixelRatio||1);matchReplaySize={width:rect.width,height:rect.height,dpr};canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);}
function drawMatchReplay(){
 if(!matchReplayDialog.open||!matchReplayClip)return;const canvas=$('match-replay-field'),size=matchReplaySize;if(!canvas||!size?.width||!size.height)return;const v=MatchPitch.frame(MatchReplay.frame(matchReplayClip,matchReplayAge)),ctx=canvas.getContext('2d');ctx.setTransform(size.dpr,0,0,size.dpr,0,0);ctx.clearRect(0,0,size.width,size.height);matchReplayPainter.drawMatch(ctx,size.width,size.height,size.dpr,season.league.division,true);
 // Replays omit tactical guides and name connector lines.
 const lift=p=>v.wallIds?.includes(p.id)?(v.wallLift||0)*8:v.headerId===p.id?(v.headerLift||0)*10:0,ballY=p=>size.height*p.y/100-(p===v.ball?v.ballHeight||0:p.height||0)*24;
 const x=p=>size.width*p.x/100,y=p=>size.height*p.y/100,r=Math.max(4,Math.min(8,size.width/50)),people=[...v.own.map(p=>({...p,team:0})),...v.opponent.map(p=>({...p,team:1}))];
 for(const p of people){ctx.fillStyle='rgba(0,0,0,.3)';ctx.beginPath();ctx.ellipse(x(p),y(p)+r+2,r*1.1,r*.45,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=p.pos==='GK'?(p.team?'#ffc078':'#8ed4fb'):p.team?'#dde9ee':'#e3263b';ctx.strokeStyle=p.id===v.performerId&&v.phase==='shot'?'#ffe28a':p.team?'#8197a4':'#ffacb5';ctx.lineWidth=p.id===v.performerId&&v.phase==='shot'?3:1;ctx.beginPath();ctx.arc(x(p),y(p)-lift(p),r,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle=p.team||p.pos==='GK'?'#10212a':'#fff';ctx.font='bold '+Math.max(8,r+1)+'px sans-serif';ctx.textAlign='center';ctx.fillText(p.no,x(p),y(p)-lift(p)+3);
 }
 if(v.trail.length){ctx.strokeStyle='#ffe28a';ctx.lineWidth=2;ctx.beginPath();for(let i=0;i<v.trail.length;i++)ctx[i?'lineTo':'moveTo'](x(v.trail[i]),ballY(v.trail[i]));ctx.lineTo(x(v.ball),ballY(v.ball));ctx.stroke();}
 // Complete both teams before drawing names, so a nearby opponent cannot hide
 // the attacker's name. Keep the foreground ball above labels and the route.
 matchReplayNames=Movement.paintNames(ctx,v,size.width,size.height,matchReplayNames);const names=matchReplayNames.map(p=>(p.team?'상대 ':'우리 ')+p.fullName).join(', ');if(canvas._names!==names){canvas._names=names;canvas.setAttribute('aria-label',names);}
 ctx.fillStyle='rgba(0,0,0,.55)';ctx.beginPath();ctx.ellipse(x(v.ball)+2,y(v.ball)+4,5,2,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';ctx.strokeStyle='#f7d268';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(x(v.ball),ballY(v.ball),4,0,Math.PI*2);ctx.fill();ctx.stroke();
 if(matchReplayPhase!==v.phase+':'+v.label){matchReplayPhase=v.phase+':'+v.label;$('match-replay-stage').textContent=v.label;$('match-replay-commentary').textContent=v.commentary||v.label;}
 const slider=$('match-replay-progress');slider.value=String(Math.round(matchReplayAge));const elapsed=(matchReplayAge/1000).toFixed(1)+' / '+(matchReplayClip.duration/1000).toFixed(1)+'초';if($('match-replay-time').textContent!==elapsed){slider.setAttribute('aria-valuetext',elapsed);$('match-replay-time').textContent=elapsed;}
}
function matchReplayTick(now){
 matchReplayRAF=null;if(!matchReplayDialog.open||document.hidden){stopMatchReplay();return;}if(!matchReplayPlaying)return;
 if(matchReplayClock!==null&&now-matchReplayClock<33){matchReplayRAF=requestAnimationFrame(matchReplayTick);return;}if(matchReplayClock!==null)matchReplayAge=Math.min(matchReplayClip.duration,matchReplayAge+Math.min(150,now-matchReplayClock)*Math.min(matchReplaySpeed,Movement.playbackRate('rapid',matchReplayAge,matchReplayPhase?.split(':')[0]||'')));matchReplayClock=now;drawMatchReplay();
 if(matchReplayAge>=matchReplayClip.duration)stopMatchReplay();else matchReplayRAF=requestAnimationFrame(matchReplayTick);
}
var continuousReplayRequest=0;
async function selectMatchReplay(id){
 const request=++continuousReplayRequest;stopMatchReplay();if(state?.continuousSetup){$('match-replay-heading').textContent='경기 장면을 준비하고 있습니다…';$('match-replay-actor').textContent='공과 선수의 이동을 확인합니다';for(const id of ['match-replay-play','match-replay-prev','match-replay-next','match-replay-progress'])$(id).disabled=true;await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));if(request!==continuousReplayRequest||!matchReplayDialog.open)return;}const clip=MatchReplay.prepare(season,Number(id),{pendingEvent:pendingVisibleMatchEvent(),positions:season.plan?.positions||{}});if(!clip.valid)return closeMatchReplay();matchReplayClip=clip;matchReplayAge=0;matchReplayNames=[];matchReplayPhase=null;stopMatchReplay();
 for(const id of ['match-replay-play','match-replay-prev','match-replay-next','match-replay-progress'])$(id).disabled=false;$('match-replay-scene').value=String(id);$('match-replay-heading').textContent=clip.scene.label;$('match-replay-actor').textContent=clip.scene.actorName||clip.club.name+'의 공격';$('match-replay-progress').max=String(clip.duration);$('match-replay-caption').textContent='당시 지시 · '+({press:'몰아붙이기',balanced:'균형 유지',counter:'내려서 역습',lowBlock:'로우 블록'}[clip.input.match.tactic])+' · '+clip.input.positions.length+':'+(11-clip.input.dismissedOpponent.length)+'명';drawMatchReplay();
}
function openMatchReplay(opener,sceneId=null){
 if(matchReplayDialog.open)return;
 if(view!=='match'||state!==season.match||typeof practiceSession!=='undefined'&&practiceSession)return;const list=MatchReplay.read(season,{pendingEvent:pendingVisibleMatchEvent()});if(!list.scenes.length)return;pauseForPlanning();matchReplayList=list;matchReplayOpener=opener||document.activeElement;matchReplaySpeed=1;matchReplayDialog.innerHTML='<header><div><small>경기 기록실</small><h2 id="match-replay-title">주요 장면 다시 보기</h2></div><details class="replay-help"><summary>안내</summary><div><p>'+escapeText(list.note)+'</p><p>기록·선수 체력·경기 시간은 바뀌지 않습니다. 닫은 후 경기 화면에서 직접 재개하세요.</p></div></details><button type="button" id="match-replay-close">닫기</button></header><label for="match-replay-scene">기록된 장면<select id="match-replay-scene">'+list.scenes.map(e=>'<option value="'+e.id+'">'+escapeText(e.label)+'</option>').join('')+'</select></label><div class="match-replay-headline"><b id="match-replay-heading"></b><span id="match-replay-actor"></span></div><p id="match-replay-caption"></p><div class="match-replay-pitch"><canvas id="match-replay-field" aria-label="기록된 공격 장면의 선수와 공"></canvas><span id="match-replay-stage"></span></div><p id="match-replay-commentary" aria-live="off"></p><label for="match-replay-progress">장면 위치 <span id="match-replay-time"></span><input id="match-replay-progress" type="range" min="0" max="1" step="1" value="0"></label><div class="match-replay-actions"><button type="button" id="match-replay-prev">이전 장면</button><button type="button" id="match-replay-play" aria-pressed="false">장면 재생</button><button type="button" id="match-replay-next">다음 장면</button><label for="match-replay-speed">재생 속도<select id="match-replay-speed"><option value="0.5">0.5배속</option><option value="1" selected>1배속</option><option value="2">2배속</option></select></label></div>';
 $('match-replay-close').onclick=closeMatchReplay;$('match-replay-scene').onchange=e=>selectMatchReplay(e.target.value);
 $('match-replay-progress').oninput=e=>{stopMatchReplay();matchReplayAge=Number(e.target.value);matchReplayNames=[];drawMatchReplay();};$('match-replay-speed').onchange=e=>{matchReplaySpeed=Number(e.target.value);};
 for(const [name,step] of [['prev',-1],['next',1]])$('match-replay-'+name).onclick=()=>{const index=matchReplayList.scenes.findIndex(s=>s.id===matchReplayClip.scene.id);selectMatchReplay(matchReplayList.scenes[(index+step+list.scenes.length)%list.scenes.length].id);};
 $('match-replay-play').onclick=()=>{if(matchReplayPlaying)return stopMatchReplay();if(matchReplayAge>=matchReplayClip.duration){matchReplayAge=0;matchReplayNames=[];}matchReplayPlaying=true;matchReplayClock=null;$('match-replay-play').textContent='재생 정지';$('match-replay-play').setAttribute('aria-pressed','true');matchReplayRAF=requestAnimationFrame(matchReplayTick);};
 matchReplayDialog.showModal();document.documentElement.classList.add('match-replay-open');measureMatchReplay();selectMatchReplay(list.scenes.find(e=>e.id===sceneId)?.id??list.scenes.at(-1).id);$('match-replay-close').focus({preventScroll:true});
}
function closeMatchReplay(){continuousReplayRequest++;stopMatchReplay();const opener=matchReplayOpener;matchReplayClip=null;matchReplayList=null;matchReplaySize=null;matchReplayOpener=null;matchReplayPhase=null;if(matchReplayDialog.open)matchReplayDialog.close();document.documentElement.classList.remove('match-replay-open');if(opener?.isConnected&&opener.getClientRects().length)opener.focus({preventScroll:true});}
matchReplayDialog.addEventListener('cancel',e=>{e.preventDefault();closeMatchReplay();});matchReplayDialog.addEventListener('close',()=>{stopMatchReplay();document.documentElement.classList.remove('match-replay-open');});
matchReplayDialog.addEventListener('click',e=>{if(e.target!==matchReplayDialog)return;const r=matchReplayDialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeMatchReplay();});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopMatchReplay();});window.addEventListener('resize',()=>{if(matchReplayDialog.open){measureMatchReplay();drawMatchReplay();}});
const matchReplayEntry=document.createElement('section');matchReplayEntry.id='match-replay-entry';matchReplayEntry.hidden=true;$('match-popup-stats').prepend(matchReplayEntry);
const matchReplayOriginalPopup=renderMatchPopup;renderMatchPopup=function(){matchReplayOriginalPopup();renderMatchReplayEntry();};
